// Journal entries (M4), the same rules as save_entry (moodbow-app migration
// 002): a non-blank body of at most 20,000 characters, a date that isn't in
// the future, and an optional "moment" flag. The id is generated by the
// client when the draft starts, so retrying a save never makes a second
// entry. The server checks everything again.

export const MAX_ENTRY_CHARS = 20000;

export type Entry = {
  id: string;
  entry_date: string;
  body: string;
  is_moment: boolean;
  updated_at: string;
};

export const ENTRY_COLUMNS = "id, entry_date, body, is_moment, updated_at";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

export const isEntryId = (id: string) => UUID.test(id);

export type EntryInput = { id: string; date: string; body: string; isMoment: boolean; expected: string | null };

// Parses the editor's form fields; null when anything is malformed.
export function parseEntry(form: FormData): EntryInput | null {
  const id = String(form.get("id") ?? "");
  const date = String(form.get("entry_date") ?? "");
  // Line breaks as \n, like the app and the editor's text area: a browser
  // sends form text with \r\n (multipart encoding), which would be stored
  // as-is, count twice against the 20,000 limit, and differ from the
  // editor's copy (a false "unsaved" or "changed elsewhere"; Web Tester, #51).
  const body = String(form.get("body") ?? "").replace(/\r\n?/g, "\n");
  const expected = String(form.get("expected_updated_at") ?? "") || null;
  if (!isEntryId(id) || !ISO_DATE.test(date) || body.trim() === "" || body.length > MAX_ENTRY_CHARS) return null;
  return { id, date, body, isMoment: form.get("is_moment") === "true", expected };
}

// True when a saved entry holds exactly this text, date and moment flag.
export const sameEntry = (row: Entry, input: Pick<EntryInput, "body" | "date" | "isMoment">) =>
  row.body === input.body && row.entry_date === input.date && row.is_moment === input.isMoment;

// The first `max` characters of a text as people see them (never half an
// emoji or a split accent).
export function preview(text: string, max = 240): string {
  const graphemes = Array.from(new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(text), (s) => s.segment);
  return graphemes.length <= max ? text : graphemes.slice(0, max).join("");
}

// The RPC's error codes (supabase/contracts/errors.md) → what the editor does.
export type EntryError = "dateInFuture" | "stale" | "tooLong" | "generic";
export type EntryErrorAction = { kind: "error"; error: EntryError } | { kind: "redirect"; to: "/consent" | "/sign-in" };

export function entryErrorAction(message: string): EntryErrorAction {
  if (message.includes("consent_required")) return { kind: "redirect", to: "/consent" };
  if (message.includes("not_authenticated")) return { kind: "redirect", to: "/sign-in" };
  if (message.includes("date_in_future")) return { kind: "error", error: "dateInFuture" };
  if (message.includes("stale_write")) return { kind: "error", error: "stale" };
  if (message.includes("entry_too_long")) return { kind: "error", error: "tooLong" };
  return { kind: "error", error: "generic" };
}
